const rooms = document.querySelectorAll('.room-item, [class*="room"], [class*="house-item"]');
const result = [];
document.querySelectorAll('h4').forEach(h => {
  if (h.textContent.includes('层')) {
    const floor = h.textContent;
    let sibling = h.nextElementSibling;
    while (sibling) {
      const roomEl = sibling.querySelector('[class*="room-num"], [class*="room-namber"], [class*="fanghao"]');
      if (roomEl) {
        result.push(floor + ' ' + roomEl.textContent.trim());
      }
      sibling = sibling.nextElementSibling;
      if (sibling && sibling.tagName === 'H4') break;
    }
  }
});
result.length > 0 ? result : 'No rooms found';
EOF

