cat <<'EOF' | agent-browser eval --stdin
// Look for rooms with "快" indicator which means expiring soon
const floorHeadings = document.querySelectorAll('h4');
const rooms = [];
floorHeadings.forEach(h => {
  if (h.textContent.includes('层')) {
    let sibling = h.nextElementSibling;
    let floor = h.textContent.replace('层', '');
    while (sibling) {
      // Check for room number elements
      const roomNum = sibling.querySelector('[class*="room-num"], [class*="fanghao"], [class*="roomNum"]');
      if (roomNum) {
        rooms.push(floor + '层 ' + roomNum.textContent.trim());
      }
      // Also check for the "快" (expiring) indicator
      const快 = sibling.querySelector('[class*="快"]');
      if (快) {
        const num = sibling.querySelector('[class*="num"]') || sibling;
